}
'''</code></pre> ​从悦​数图​数据库​导入​完整​图到​临时​图​。 <pre><code>'''
USE #movie_import_2 IMPORT INTO GRAPH 
{
  NODE (v@Actor{id:id, name:name}) FROM NEBULA { 
    FORMAT: "NEBULA", 
    PATH: "nebula://root:Yueshu01@192.168.8.129:20000?graph=movie&amp;node_type=Actor"
  },
  NODE (v@Movie{id:id, name:name}) FROM NEBULA { 
    FORMAT: "NEBULA", 
    PATH: "nebula://root:Yueshu01@192.168.8.129:20000?graph=movie&amp;node_type=Movie"
  },
  EDGE (id:id)-[e@Act{}]-&gt;(id:id) FROM NEBULA { 
    FORMAT: "NEBULA", 
    PATH: "nebula://root:Yueshu01@192.168.8.129:20000?graph=movie&amp;edge_type=Act"
  }
}
'''</code></pre> ​从悦​数图​数据库​导入​特定​点​和​边​到​临时​图​。 <pre><code>'''
USE #pagerank_graph IMPORT INTO GRAPH 
  { 
    NODE (v@Person {id: u_id, name: u_name}) FROM DATAFILE { 
        PATH: "file:///home/user1/test/pagerank_node.csv", 
        FORMAT: "CSV", 
        DELIMITER: ',' 
    }, 
    EDGE (id: src_id, name: src_name)-[e@Knows{}]-&gt;(id: dst_id, name: dst_name) FROM DATAFILE { 
        PATH: "file:///home/user1/test/pagerank_edge.csv", 
        FORMAT: "CSV", 
        DELIMITER: ',' 
    } 
  } OPTIONS {PRIMARY_KEY_AS_NODE_ID:false} 
'''</code></pre> ​直接​从​ CSV ​文件​导入​数据​到​临时​图​。 <pre><code>'''
FILE node_file { id INT } = DATAFILE { 
    PATH:"file:///home/user1/test/wcc_node.csv", 
    FORMAT:"CSV"
}
FILE edge_file { src INT, dst INT } = DATAFILE {
    PATH:"file:///home/user1/test/wcc_edge.csv",
    FORMAT:"CSV"
}
USE #wcc_graph IMPORT INTO GRAPH { 
    NODE (v@Person {id: id}) FROM node_file, 
    EDGE (id: src)-[e@Knows{}]-&gt;(id: dst) FROM edge_file 
  }
'''</code></pre> ​使用​文件​变量​从​ CSV ​文件​导入​数据​到​临时​图​。

Statement Description <pre><code>'''
USE #movie_temporary_graph { 
   FILE f { nodes STRING, edges STRING } = DATAFILE {PATH:"file:///home/user1/test", FORMAT:"CSV", INCLUDE_HEADER: true} 
   MATCH (v@`User`)-[e]-(m@Movie) WHERE e.rate = 5.0 AND v.id &gt; 605 
   PER PATH { 
       EXPORT v, e INTO f
   } 
}
'''</code></pre> ​将点​和​边​导出​到​ CSV ​文件​。 <pre><code>'''
USE #movie_temporary_graph { 
   FILE f { user_id INT, rate DOUBLE, movie_name STRING } = DATAFILE {PATH:"file:///home/user1/test", FORMAT:"CSV", INCLUDE_HEADER: true} 
   MATCH (v@`User`)-[e]-(m@Movie) WHERE e.rate = 5.0 AND v.id &gt; 605 
   PER PATH { 
       EXPORT v.id, e.rate, m.name INTO f
   } 
}
'''</code></pre> ​将点​和​边​的​属性​导出​到​ CSV ​文件​。 <pre><code>'''
USE #movie_temporary_graph { 
   NODE VALUE a MaxAgg = 280000 
   NODE VALUE b MinAgg = 280000 
   TABLE t TYPED TABLE { original_id INT, maxed_id INT, mined_id INT } 
   MATCH (v@Actor) WHERE v.id &gt; 271940 
   PER NODE (v) { 
       SET v.@a += v.id 
       SET v.@b += v.id
   } 
   MATCH (v@Actor) WHERE v.id &gt; 271940 
   PER NODE (v) { 
       EXPORT v.id, v.@a, v.@b INTO t
   } 
   FOR r IN t 
   RETURN r.original_id AS original_id, r.maxed_id AS maxed_id, r.mined_id AS mined_id 
}
'''</code></pre> ​将点​绑定​的​聚合​值​导出​到​表格​中​。

语句​ ​描述​ <pre><code>'''
USE #match_compute_movie {
  /* ====== ​声明​ ====== */
  VALUE source_id = 1                          // ​用于​相似​度​计算​的​源​用户​ ID
  VALUE source_edges    SumAgg = 0      // ​源​用户​喜欢​的​电影​
  VALUE topk_similarity TopKAgg&lt;5, similarity DOUBLE DESC, id INT DESC&gt;  // ​前​ 5 ​位​相似​用户​
  NODE VALUE target_edges SumAgg = 0    // ​每个​用户​喜欢​的​电影​
  NODE VALUE intersection SumAgg = 0    // ​与源​用户​的​共同​喜欢​的​电影​
  VALUE v_set ACTIVE_SET                       // ​源​用户​喜欢​的​电影​

  /* ====== ​步骤​ 1：​统计​用户​电影​偏好​ ====== */
  // ​统计​所有​用户​喜欢​的​电影​
  MATCH (u@User)-[e:Watch]-&gt;(m:Movie)
  PER PATH {
    SET u.@target_edges += 1                  // ​每个​用户​的​电影​计数​递增​
  }

  /* ====== ​步骤​ 2：​收集​源​用户​数据​ ====== */
  // ​处理​源​用户​的​偏好​
  MATCH (u@User)-[:Watch]-&gt;(m:Movie) 
  WHERE u.id = source_id  // ​筛选​源​用户​
  PER NODE (u) {
    SET @source_edges += u.@target_edges     // ​存储​源​用户​的​电影​计数​
  }
  FINALLY { SET v_set = m }                      // ​用源​用户​的​电影​填充​活动​集​

  /* ====== ​步骤​ 3：​计算​用户​相似​度​ ====== */
  // ​查找​源​用户​与​其他​用户​的​共同​喜欢​电影​
  MATCH (m:Movie)&lt;-[:Watch]-(t@User) 
  WHERE t.id &lt;&gt; source_id AND m IN v_set                  // ​排除​源​用户​，​使用​源​用户​的​电影​作为​起点​
  PER PATH {
    SET t.@intersection += 1                 // ​统计​共同​电影​
  }
  PER NODE (t) {
    // ​计算​源​用户​和​其他​用户​的​共同​喜欢​电影​的​并​集​
    VALUE union_size = t.@target_edges + @source_edges - t.@intersection

    IF union_size &lt;&gt; 0 THEN {
      VALUE similarity = CAST(t.@intersection AS DOUBLE) / union_size

      // ​存储​到​前​ k ​聚合​器​
      SET @topk_similarity += RECORD{
        similarity: similarity, 
        id: t.id
      }
    }
  }

  /* ====== ​步骤​ 4：​返回​结果​ ====== */
  // ​输出​前​ 5 ​位​相似​用户​
  FOR r IN @topk_similarity
    RETURN r.id AS user_id, 
          ROUND(r.similarity, 5) AS jaccard_similarity
}
'''
</code></pre> ​基于​用户​的​电影​偏好​计算​用户​之间​的​ Jaccard ​相似​度​。

语句​ ​描述​ <pre><code>'''
USE #movie_temporary_graph { 
    VALUE a INT = 1 
    VALUE b INT = 1 
    VALUE c INT = 1 
    SET a = a + 1 
    SET b = a + 2 
    SET c = b + 3 
    RETURN a, b, c 
}
'''</code></pre> ​为​原始​值​变量​赋值​。 <pre><code>'''
USE #movie_temporary_graph { 
    VALUE a SumAgg = 0 
    VALUE b MaxAgg = 0.0 
    VALUE c OrAgg = false 
    SET @a = 10 
    SET @b = 20.5 
    SET @c = true 
    RETURN @a, @b, @c 
}
'''</code></pre> ​为​全局​聚合​值​变量​赋值​。 <pre><code>'''
USE #movie_temporary_graph { 
  NODE VALUE a ListAgg 
  MATCH (v@Actor) WHERE v.id &gt; 271940 
  PER NODE (v) { 
    SET v.@a = LIST[v.id] 
    LOG_INFO("ID_List: ", v.@a) 
  } 
}
'''</code></pre> ​为点​绑定​聚合​值​变量​赋值​。 <pre><code>'''
USE #movie_temporary_graph { 
    VALUE active_set ACTIVE_SET 
    VALUE list_id ListAgg

    MATCH (a@Actor) WHERE a.id IN [31, 8252] 
    PER NODE (a) { 
        // ​将​匹配​到​的​点​的​唯一​标识符​（UID）​添加​到​列表​中​
        SET @list_id += element_id(a)
    }
    // ​将点​的​ UID ​列表​赋值​给​活动​集​变量​
    SET active_set = @list_id

    MATCH (a) 
    WHERE a IN active_set 
    PER NODE (a) { 
        LOG_INFO("Actor Name: ", a.name) 
    } 
}
'''
</code></pre> ​为​活动​集​变量​赋值​。 <pre><code>'''
USE #movie_temporary_graph {
  VALUE global_avg AvgAgg
  SET @global_avg += 3     // Average: 3.0 (Total: 3, Count: 1)
  SET @global_avg += 7     // Average: 5.0 (Total: 10, Count: 2)
  SET @global_avg += 5     // Average: 5.0 (Total: 15, Count: 3)
  LOG_INFO("@global_avg: ",@global_avg)
}
'''
</code></pre> ​将值​聚合​到​全局​聚合​值​变量​中​。 <pre><code>'''
USE #movie_temporary_graph {
  NODE VALUE node_avg AvgAgg

  MATCH (a@User WHERE a.id IN [1,3,4])-[w@Watch]-&gt;(b@Movie)
  PER PATH {
    // ​累加​用户​对​观看​电影​的​评分​并​计算​平均值​
    SET a.@node_avg += w.rate
  }
  PER NODE (a) {
    LOG_INFO("a.id: ",a.id, " a.@node_avg: ",a.@node_avg)
  }
}
'''
</code></pre> ​将值​聚合​到​点​绑定​聚合​值​变量​中​。 <pre><code>'''
USE #movie_temporary_graph {
  VALUE global_set_1 SetAgg
  SET @global_set_1 += 3    // set: {3}
  SET @global_set_1 += 7    // set: {3, 7}  
  SET @global_set_1 += 3    // set: {3, 7} (duplicate ignored)
  SET @global_set_1 += 5    // set: {3, 7, 5}
  LOG_INFO("@global_set_1: ", @global_set_1)

  SET @global_set_1.clear() // set: {}
  LOG_INFO("@global_set_1: ", @global_set_1)
}
'''
</code></pre> ​调用​聚合​值​变量​的​成员​函数​。

语句​ ​描述​ <pre><code>'''
VALUE i INT = 0 
WHILE i &lt; 5 THEN { 
  SET i = i + 1 
} 
RETURN i
'''
</code></pre> ​使用​<code>WHILE</code>​循环​重复​执行​一段​语句​块​。 <pre><code>'''
VALUE i INT = 4 
IF i &lt; 3 THEN { 
  SET i = i + 1 
} ELSEIF i &lt; 5 THEN { 
  SET i = i + 2 
} ELSE { 
  SET i = i - 1 
} 
RETURN i
'''
</code></pre> ​使用​<code>IF-ELSEIF-ELSE</code>​语句​有​条件​地​执行​一段​语句​块​。 <pre><code>'''
VALUE i INT = 0 
WHILE i &lt; 5 THEN { 
  IF i = 3 THEN { 
    BREAK 
    } 
  SET i = i + 1 
} 
RETURN i 
'''
</code></pre> ​使用​<code>BREAK</code>​语句​退出​循环​。 <pre><code>'''
VALUE i INT = 0 
WHILE i &lt; 5 THEN { 
  IF i &lt; 3 THEN { 
    SET i = i + 1 
    CONTINUE 
  } ELSE { 
    SET i = i + 1 
  } 
} 
RETURN i
'''
</code></pre> ​使用​<code>CONTINUE</code>​语句​跳过​当前​迭代​中​剩余​的​语句​并​进入​下​一次​迭代​。

语句​ ​描述​ <pre><code>'''
USE #movie_temporary_graph { 
  VALUE w SumAgg = 0 
  MATCH ()-[e:Watch]-() 
  PER PATH { 
    SET @w += 1 
  } 
  LOG_INFO("Finish Iteration") 
  LOG_WARN("Final w: ", @w) 
  RETURN @w AS watch_count 
}
'''
